def eval_expression(expr: str) -> float:
    """
    Evaluate a mathematical expression string with support for:
    - Addition (+), Subtraction (-), Multiplication (*), Division (/)
    - Parentheses for grouping
    - Negative numbers
    - Proper order of operations (PEMDAS/BODMAS)

    Raises ZeroDivisionError if division by zero is encountered.
    """
    tokens = _tokenize(expr)
    pos = [0]

    def peek():
        if pos[0] < len(tokens):
            return tokens[pos[0]]
        return None

    def consume():
        token = tokens[pos[0]]
        pos[0] += 1
        return token

    def parse_expression():
        """Parse addition and subtraction (lowest precedence)"""
        result = parse_term()
        while peek() in ('+', '-'):
            op = consume()
            right = parse_term()
            if op == '+':
                result += right
            else:
                result -= right
        return result

    def parse_term():
        """Parse multiplication and division (higher precedence)"""
        result = parse_factor()
        while peek() in ('*', '/'):
            op = consume()
            right = parse_factor()
            if op == '*':
                result *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                result /= right
        return result

    def parse_factor():
        """Parse unary plus/minus and primary expressions (highest precedence)"""
        if peek() in ('+', '-'):
            op = consume()
            operand = parse_factor()
            if op == '-':
                return -operand
            return operand
        return parse_primary()

    def parse_primary():
        """Parse numbers or parenthesized expressions"""
        token = peek()
        if token is None:
            raise ValueError("Unexpected end of expression")
        if token == '(':
            consume()  # consume '('
            result = parse_expression()
            if peek() != ')':
                raise ValueError("Expected closing parenthesis")
            consume()  # consume ')'
            return result
        elif token == 'number':
            consume()
            return token['value']
        else:
            raise ValueError(f"Unexpected token: {token}")

    return parse_expression()


def _tokenize(expr: str):
    """Tokenize the expression string into a list of tokens."""
    tokens = []
    i = 0
    expr = expr.replace(' ', '')

    while i < len(expr):
        ch = expr[i]

        if ch in '+-*/()':
            if ch == '+':
                # Check if this is part of a number (e.g., after nothing or after operator/opening paren)
                # Actually, unary +/- is handled in parse_factor
                tokens.append(ch)
            elif ch == '-':
                tokens.append(ch)
            else:
                tokens.append(ch)
            i += 1
        elif ch.isdigit() or ch == '.':
            # Parse number
            j = i
            has_dot = False
            while j < len(expr) and (expr[j].isdigit() or (expr[j] == '.' and not has_dot)):
                if expr[j] == '.':
                    has_dot = True
                j += 1
            num_str = expr[i:j]
            tokens.append({'type': 'number', 'value': float(num_str)})
            i = j
        else:
            raise ValueError(f"Unexpected character: {ch}")

    return tokens
